<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();$active='dashboard';$pageTitle='ড্যাশবোর্ড';
$counts=['notices'=>0,'published'=>0,'draft'=>0,'courses'=>0,'applications'=>0,'diploma_programs'=>0,'posts'=>0];
$queries=['notices'=>"SELECT COUNT(*) FROM notices",'published'=>"SELECT COUNT(*) FROM notices WHERE status='published'",'draft'=>"SELECT COUNT(*) FROM notices WHERE status='draft'",'courses'=>"SELECT COUNT(*) FROM courses WHERE status='active'",'applications'=>"SELECT COUNT(*) FROM applications WHERE status='new'",'posts'=>"SELECT COUNT(*) FROM content_posts WHERE status='published'"];
foreach($queries as $k=>$q){try{$counts[$k]=(int)$pdo->query($q)->fetchColumn();}catch(Throwable $e){}}
$settings=[];try{foreach($pdo->query("SELECT setting_key,setting_value FROM site_settings")->fetchAll() as $r)$settings[$r['setting_key']]=$r['setting_value'];}catch(Throwable $e){}
$programs=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)($settings['diploma_programs']??"কম্পিউটার সায়েন্স অ্যান্ড টেকনোলজি (CST)\nইলেকট্রিক্যাল টেকনোলজি (ET)")))));$counts['diploma_programs']=count($programs);
$semesters=trim((string)($settings['diploma_semesters']??''));
try{$latest=$pdo->query('SELECT id,title,notice_date,status FROM notices ORDER BY created_at DESC LIMIT 5')->fetchAll();}catch(Throwable $e){$latest=[];}
try{$recentApps=$pdo->query('SELECT a.id,a.applicant_name,a.phone,a.status,a.created_at,c.title course_title FROM applications a LEFT JOIN courses c ON c.id=a.course_id ORDER BY a.created_at DESC LIMIT 5')->fetchAll();}catch(Throwable $e){$recentApps=[];}
try{$activity=$pdo->query('SELECT action,details,created_at FROM activity_logs ORDER BY created_at DESC LIMIT 5')->fetchAll();}catch(Throwable $e){$activity=[];}
require __DIR__.'/_head.php';
?>
